using System;using System.Linq;using System.Reflection;using System.Collections;using UnityEngine;using UnityEditor;using UnityEngine.InputSystem;
public static class TextureV7Cleanup {
 public static object Run(){const BindingFlags f=BindingFlags.Instance|BindingFlags.Public|BindingFlags.NonPublic;var manager=typeof(InputSystem).GetField("s_Manager",BindingFlags.Static|BindingFlags.NonPublic).GetValue(null);var callbacks=manager.GetType().GetField("m_AfterUpdateListeners",f).GetValue(manager);var t=callbacks.GetType();int n=(int)t.GetProperty("length").GetValue(callbacks),removed=0;for(int i=0;i<n;i++){var d=(Delegate)t.GetProperty("Item").GetValue(callbacks,new object[]{i});if(d.Method.DeclaringType.FullName.Contains("TextureV7Review")){InputSystem.onAfterUpdate-=(Action)d;removed++;}}
 foreach(var d in InputSystem.devices.Where(x=>x.name.StartsWith("V7Review")).ToArray())InputSystem.RemoveDevice(d);InputSystem.devices.OfType<Keyboard>().FirstOrDefault()?.MakeCurrent();InputSystem.devices.OfType<Mouse>().FirstOrDefault()?.MakeCurrent();var saved=Resources.FindObjectsOfTypeAll<InputSettings>().Where(s=>!ReferenceEquals(s,InputSystem.settings)).ToArray();if(saved.Length==1)InputSystem.settings=saved[0];
