 EditorApplication.UnlockReloadAssemblies();return new{removedCallbacks=removed,temporaryDevices=InputSystem.devices.Count(d=>d.name.StartsWith("V7Review")),scene=UnityEngine.SceneManagement.SceneManager.GetActiveScene().name,playing=EditorApplication.isPlaying,focus=InputSystem.settings.editorInputBehaviorInPlayMode.ToString(),background=InputSystem.settings.backgroundBehavior.ToString()};}
}
